<?php
namespace App\Policies;use App\Models\{ClaimDispute,User};final class ClaimDisputePolicy{public function viewAny(User$u):bool{return$u->memberships()->where('status','ACTIVE')->whereIn('role_code',['SYSTEM_ADMIN','PLATFORM_ADMIN','CLAIMS_MANAGER','COMPLIANCE_ADMIN'])->exists();}public function view(User$u,ClaimDispute$m):bool{return$this->viewAny($u)&&$m->claim()->where('tenant_id',app(\App\Domain\Tenancy\TenantContext::class)->id())->exists();}public function create(User$u):bool{return$this->viewAny($u);}public function update(User$u,ClaimDispute$m):bool{return$this->view($u,$m);}public function delete(User$u,ClaimDispute$m):bool{return false;}}
